 @Override Peer select(String tag,int port,String account,String source,String character)throws Exception{
  stage="authenticate-select:"+tag;save();try(Peer login=loginReady(tag,port,account)){
   var directory=new Protocol.Reader(login.await(Protocol.S_SERVER_LIST));directory.c();int count=directory.c();boolean found=false;for(int i=0;i<count;i++){String name=directory.s();long address=directory.d();int routePort=directory.h();if(name.equals(source)){require(address==0x0200007fL&&routePort==port,"actual selected source route");found=true;}}require(found&&directory.remaining()==0,"actual source advertised");login.await(Protocol.S_LITO_VS_SERVER_STATUS);login.send(new Protocol.Writer().c(Protocol.C_LITO_LIN_CHARACTER_INFO).s(source).bytes());var route=new Protocol.Reader(login.await(Protocol.S_LITO_VS_SERVER_IP));route.c();require(route.c()==0&&route.d()==0x0200007fL&&route.h()==port&&route.remaining()==0,"actual source redirect");
   Peer game=new Peer(tag+"-GAME","127.0.0.2",port);try{game.auth(account);game.await(Protocol.S_LITO_NEWS);game.send(new Protocol.Writer().c(Protocol.C_LITO_READ_NEWS).bytes());var countRow=new Protocol.Reader(game.await(Protocol.S_NUM_CHARACTER));countRow.c();require(countRow.c()==1&&countRow.remaining()==0,"actual one owned directory row");byte[] packet=game.await(Protocol.S_LITO_CHARACTER_INFO);var row=new Protocol.Reader(packet);row.c();String alias=row.s(),clan=row.s();boolean caster=account.equals("WireSend");int type=row.c(),sex=row.c();row.h();int hp=row.h(),mp=row.h();require(alias.equals(account+"("+source+")")&&clan.equals("OwnedRunClan"+(source.equals(SUN)?"A":"B")),"actual selected directory alias/clan match owned SQL");require(type==(caster?0:1)&&sex==0&&hp==200&&mp==(caster?200:100),"actual royal/member directory class and vitals");row.c();require(row.c()==52,"actual level52");for(int i=0;i<7;i++)row.c();for(int i=0;i<10;i++)row.d();row.c();for(int i=0;i<5;i++)row.d();row.c();require(row.remaining()==0,"bounded actual S_CB fields");game.send(new Protocol.Writer().c(Protocol.C_LITO_SELECT_CHAR).s(alias).bytes());require(Arrays.equals(game.await(Protocol.litoCharacterSelectResult(Protocol.LitoCharacterSelectResult.ACCEPTED)[0]&255),Protocol.litoCharacterSelectResult(Protocol.LitoCharacterSelectResult.ACCEPTED)),"actual C_C9 accepted");game.await(Protocol.S_ADD_INVENTORY_BATCH);evidence.put("authenticated_selection",true);checks.add(Map.ofEntries(Map.entry("case","genuine LOGIN/GAME selection"),Map.entry("peer",tag),Map.entry("account",account),Map.entry("source",source),Map.entry("character",character),Map.entry("server_issued_selection_name",alias),Map.entry("directory_clan",clan),Map.entry("directory_type",type),Map.entry("directory_HP",hp),Map.entry("directory_MP",mp),Map.entry("S_CB_payload_hex",HexFormat.of().formatHex(packet)),Map.entry("controlled_selection",false)));save();return game;}catch(Throwable failure){game.close();throw failure;}
  }
 }
