 @Override Map<String,Object> snapshot(ModernSettlementMysqlFixture mysql,String label)throws Exception{
  require(mysql.processId()==sqlPid&&nativeDatadirIdentity(mysql).equals(datadirKey),"same real owned datadir");Map<String,Object> core=new LinkedHashMap<>();
  for(String db:List.of(A,B)){Map<String,Object> row=new LinkedHashMap<>();row.put("characters",rows(mysql,db,"SELECT account_name,char_name,objid,Class,Type,ClanID,Clanname,ClanRank,LocX,LocY,MapID,Heading,CurHp,CurMp,MaxMp,level FROM characters WHERE objid IN(10001,10002) ORDER BY objid"));row.put("clans",rows(mysql,db,"SELECT clan_id,clan_name,leader_id,leader_name FROM clan_data ORDER BY clan_id"));row.put("learned_skills",rows(mysql,db,"SELECT char_obj_id,skill_id FROM character_skills ORDER BY char_obj_id,skill_id"));row.put("origin",rows(mysql,db,"SELECT char_obj_id,account_name,char_name FROM lito_character_origin ORDER BY char_obj_id"));row.put("items",rows(mysql,db,"SELECT id,item_id,char_id,count FROM character_items ORDER BY id"));core.put(db,row);}
  core.put(STATIC,Map.of("skills",rows(mysql,STATIC,"SELECT skill_id,name,skill_level,skill_number,mpConsume,reuseDelay,target_to,type,action_id,sysmsgID_fail FROM skills WHERE skill_id=118")));Path folder=root.resolve("snapshots");Files.createDirectories(folder);Map<String,Object> record=new LinkedHashMap<>();record.put("label",label);record.put("same_mysql_pid",sqlPid);record.put("datadir",mysql.dataDirectory().toRealPath().toString());record.put("datadir_file_key",datadirKey);record.put("core",core);Path state=root.resolve("native.state");record.put("sidecar_present",Files.exists(state));if(Files.exists(state))record.put("sidecar_SHA",hash(state));Files.writeString(folder.resolve(label+".json"),json(record),StandardCharsets.UTF_8);snapshots.add(record);evidence.put("SQL_snapshots",snapshots);save();return core;
 }
 Map<String,Object> cast(Peer caster,Actor target,String label)throws Exception{
  sync(caster);Map<String,Object> row=new LinkedHashMap<>();row.put("case",label);row.put("peer",caster.tag);row.put("target",actorData(target));row.put("cast_sent_utc",Instant.now().toString());row.put("cast_sent_nanos",System.nanoTime());
  byte[] request=new Protocol.Writer().c(Protocol.C_USE_SPELL).c(14).c(5).s("RecvA").bytes();row.put("C14_payload_hex",HexFormat.of().formatHex(request));caster.send(request);byte[] summon=caster.await(Protocol.S_REQUEST_SUMMON);require(Arrays.equals(summon,Protocol.requestSummon(SENDER)),"real normal Run Clan produces exact S55 self envelope");row.put("S55_payload_hex",HexFormat.of().formatHex(summon));row.put("S55_received_nanos",System.nanoTime());row.put("S55_received_utc",Instant.now().toString());row.put("native_TTL_seconds",BattleRunClan.PORTAL_TIMEOUT_SECONDS);require(BattleRunClan.PORTAL_TIMEOUT_SECONDS==30,"retained Run Clan TTL30");row.put("pending_field_directly_read",false);runCases.add(row);evidence.put("RunClan_cases",runCases);save();return row;
 }
 void age(Map<String,Object> row,String consumer)throws Exception{
  long start=((Number)row.get("S55_received_nanos")).longValue(),until=start+TimeUnit.MILLISECONDS.toNanos(31250);evidence.put("stage","waiting-real-RunClan-TTL-before-"+consumer);save();while(System.nanoTime()<until){Thread.sleep(Math.min(1000,Math.max(1,TimeUnit.NANOSECONDS.toMillis(until-System.nanoTime()))));}row.put("real_elapsed_S55_to_consumer_ms",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start));row.put("aged_consumer",consumer);row.put("consumer_after_real_TTL_utc",Instant.now().toString());save();
 }
 void returnSummon(Peer caster,int x,int y,Map<String,Object> row)throws Exception{
  row.put("C4E_sent_nanos",System.nanoTime());row.put("C4E_sent_utc",Instant.now().toString());caster.send(new Protocol.Writer().c(Protocol.C_RETURN_SUMMON).c(0).bytes());byte[] portal=caster.await(Protocol.S_PORTAL);var r=new Protocol.Reader(portal);require(r.c()==90&&r.h()==564&&r.h()==x&&r.h()==y&&r.remaining()==0,"real C4E gives expected S5A destination");row.put("S5A_payload_hex",HexFormat.of().formatHex(portal));row.put("S5A_x",x);row.put("S5A_y",y);row.put("S5A_received_nanos",System.nanoTime());save();
 }
 Actor rebuild(Peer caster,int x,int y,int heading,Map<String,Object> row)throws Exception{
  row.put("C08_sent_nanos",System.nanoTime());row.put("C08_sent_utc",Instant.now().toString());int from=caster.received.size();caster.send(new Protocol.Writer().c(Protocol.C_GOTO_PORTAL).bytes());int status=-1,selfAt=-1,hp=-1,unlock=-1,world=0;Actor self=null;List<Object> actors=new ArrayList<>();String statusHex=null,hpHex=null;
  for(int n=0;n<1000;n++){byte[] b=caster.receive();require(b!=null,"real C08 live transport");int at=caster.received.size()-1,op=b[0]&255;
   if(op==Protocol.S_STATUS){require(status<0,"one status");var r=new Protocol.Reader(b);r.c();require(r.d()==SENDER,"real caster STATUS id");status=at;statusHex=HexFormat.of().formatHex(b);}
   else if(op==Protocol.S_PUT_OBJECT){Actor a=actor(b);actors.add(actorData(a));if(a.id()==SENDER){require(self==null,"one actual rebuilt self");self=a;selfAt=at;}}
   else if(op==Protocol.S_HIT_POINT){var r=new Protocol.Reader(b);r.c();require(r.h()==200&&r.h()==200&&r.remaining()==0,"real HP200");hp=at;hpHex=HexFormat.of().formatHex(b);}
   else if(op==Protocol.S_WORLD)world++;
   else if(op==Protocol.S_PARALYSE&&Arrays.equals(b,new byte[]{0x25,7})){unlock=at;break;}
  }
  require(status>=from&&status<selfAt&&selfAt<hp&&hp<unlock&&world==0,"real STATUS self HP2507 order, no C08 WORLD");require(self!=null&&self.x()==x&&self.y()==y&&self.heading()==0,"actual rebuilt destination with retained common battle actor heading0");row.put("rebuilt_self",actorData(self));row.put("actors",actors);row.put("STATUS_received_index",status);row.put("self_received_index",selfAt);row.put("HP_received_index",hp);row.put("unlock_received_index",unlock);row.put("STATUS_payload_hex",statusHex);row.put("HP_payload_hex",hpHex);row.put("unlock_payload_hex","2507");row.put("S_WORLD_inside_C08_rebuild",world);row.put("expected_portal_peer_movement_heading",heading);sync(caster);save();return self;
 }
 void portalPeerMove(Peer witness,int x,int y,int heading,Map<String,Object> row)throws Exception{
  byte[] expected=new Protocol.Writer().c(Protocol.S_MOVE_OBJECT).d(SENDER).h(x).h(y).c(heading).bytes();boolean found=false;for(int i=0;i<1000;i++){byte[] b=witness.receive();require(b!=null,"live actual portal peer");if(Arrays.equals(b,expected)){found=true;row.put("actual_portal_peer_move_hex",HexFormat.of().formatHex(b));row.put("actual_portal_peer",witness.tag);row.put("actual_portal_peer_heading",heading);break;}}require(found,"real peer portal movement destination/heading, separate from common S0B heading0");sync(witness);save();
 }
